W=[E('onomatopoeic','英 /ˌɒnəˌmætəˈpiːɪk/；美 /ˌɑːnəˌmætəˈpiːɪk/','拟声的','词读出来，就有一点它描写的那种声音。','关联 onomatopoeia 拟声 + -ic 形容词结尾；历史上也可能经法语 onomatopoéique 进入英语。更早 onomat- 名字与 poiein 创造共同构成造词一词。',[['希腊 onomat-；poiein → onomatopoiia','名称；创造 → 造出名称或词'],['onomatopoeia 词族／法语 onomatopoéique → 英语 onomatopoeic','与拟声有关的']],'说 buzz 是 an onomatopoeic word，是说它的嗡嗡声和蜜蜂等发出的声音相像；不是说每个带嗡声的东西都叫 buzz。不同语言各有自己的模仿方式，同一种动物的叫声也未必写成同一个词。','an onomatopoeic word；onomatopoeic language；an onomatopoeic effect。','onomatopoeia 是这种造词或修辞现象的名称，onomatopoeic 用来形容某个词或表达。押韵则比较词与词的声音，不一定模仿现实声响。',('“Hiss” is an onomatopoeic word that suggests a long, sharp sound.','hiss 是一个拟声词，让人想到持续的嘶嘶声。'),('The comic uses onomatopoeic words to make the action seem louder.','这部漫画用拟声词让动作仿佛更有声响。'),sources=['https://www.etymonline.com/word/onomatopoeic','https://en.wiktionary.org/wiki/onomatopoeic#English','https://www.oxfordlearnersdictionaries.com/definition/english/onomatopoeic'])]
R=[dict(id='C0891',meaning='名字；词',core='ONOMAT = NAME / WORD',image='听见嗡嗡声，再照着声音给它造个词：名字也可以带着声音的影子。',intro='希腊 onoma 表示名字、词，属格 onomatos 露出 onomat- 词干。这个根本身并不表示声音；onomatopoeia 把名称和创造相连，现代修辞中主要指用声音模仿声响。',forms='onoma／onomat- 是同一名词的词形关系；onomatopoeia 经后期拉丁进入英语，onomatopoeic 是对应形容词。',branches=[['拟声现象','onomatopoeia'],['形容词的拟声效果','onomatopoeic']],contrasts='onomat- 不是自动等于拟声；只有结合具体整词才能确定意思。buzz、hiss 是拟声例子，不是从希腊 onomat- 派生出的英语词。',practice='Onomatopoeia is the device; onomatopoeic describes a word that uses it.\n\nonomatopoeia 是手法名称；onomatopoeic 描述用了这种手法的词。',words=['onomatopoeia','onomatopoeic'],exclude={w:'姓名学、命名学或专门修辞术语，先保留常见拟声词族。' for w in ['onomastic','onomastics','onomasticon','antonomasia','onomasiology','onomatology','onomatophore']}),
dict(id='C0144',meaning='凡人；会死的',core='BROT = MORTAL',image='凡人会死；希腊神话把神看作不朽者，神吃的食物也带着不朽的名字。',intro='希腊 brotos 表示凡人、会死的。与否定成分结合的 ambrotos 表示不死的，ambrosia 则是神食。这里的 b 与更早词形变化有关，不把现代拼写粗暴拆成 am + bro 来猜义。',forms='a- 否定 + brotos 一系 → ambrotos 不死的；ambrosia 经拉丁进入英语。brot- 与表示兄弟的 brother 不能因前几个字母相近就等同。',branches=[['不朽者的食物','ambrosia']],contrasts='ambrosia 的神话背景能帮助理解珍馐美味的比喻；现实中的菜名并不声称食物让人不死。',practice='After hours of walking, a simple meal can taste like ambrosia.\n\n走了几个小时后，一顿便饭也能吃出珍馐美味的感觉。',words=['ambrosia'],exclude={'ambrotype':'较专门的历史摄影工艺名，本轮略过。'})]
